entries[46106] = { ["name"] = "Wonderheal XT68 Shades", ["text"] = "50 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nWonderheal XT40 Shades , Primal Water (4), Primal Mana (8), Primal Nether (4)\nWonderheal XT68 Shades\nBinds when picked up\nHead Leather\n405 Armor\n+33 Stamina\n+51 Intellect\n+35 Spirit\n\nMeta Socket\nBlue Socket\nSocket Bonus: +9 Healing and +3 Spell Damage\n\nDurability 70 / 70\n70\nRequires Engineering\n(350)\nEquip: Increases healing done by up to 134 and damage done by up to 45 for all magical spells and effects.\n\nEquip: Shows the location of all nearby gas clouds on the minimap.\n\nEquip: Slightly increases your stealth detection.\n\nUse: Allows you to look far into the distance. (3 Sec Cooldown)" }
entries[46107] = { ["name"] = "Justicebringer 3000 Specs", ["text"] = "50 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nJusticebringer 2000 Specs , Primal Life (8), Primal Mana (8), Primal Earth (8), Primal Nether (4)\nJusticebringer 3000 Specs\nBinds when picked up\nHead Plate\n1611 Armor\n+48 Stamina\n+26 Intellect\n\nMeta Socket\nBlue Socket\nSocket Bonus: +4 Spell Critical Strike Rating\n\nDurability 100 / 100\n70\nRequires Engineering\n(350)\nEquip: Improves spell critical strike rating by 52.\n\nEquip: Increases healing done by up to 128 and damage done by up to 43 for all magical spells and effects.\n\nEquip: Shows the location of all nearby gas clouds on the minimap.\n\nEquip: Slightly increases your stealth detection.\n\nUse: Allows you to look far into the distance. (3 Sec Cooldown)" }
